import {ATTACKS,DEFENDERS,newMatch,incomingKey,launchAttack,tapThreat,defendWave,nextRound} from './game-core.js?v=505cdebe91a0';
const asset=(key,alt='')=>`<img src="./icons/${key}.png" alt="${alt}">`;
export function renderHackingGame(){
 return `<div class="page-heading"><div><div class="eyebrow">06 / RED TEAM × BLUE TEAM</div><h1><span class="terminal-chevron">&gt;</span>CYBER DUEL ARENA.</h1><p>보내고, 빼앗고, 막아내세요. 두 가상 컴퓨터 사이에서 펼쳐지는 6라운드 공방전.</p></div><div class="header-badge">BOT OPPONENT / VIRTUAL</div></div><div id="hacking-game"></div>`;
}
export function mountHackingGame(root){
 const host=root.querySelector('#hacking-game'),life=new AbortController(),timers=new Set();let state=null,busy=false,disposed=false,mode='duel',highScore=0,generation=0;
 try{const saved=Number(localStorage.getItem('hexlab-game-best'));if(Number.isFinite(saved)&&saved>=0&&saved<100000)highScore=saved;}catch{}
 const listen=(el,event,fn)=>el.addEventListener(event,fn,{signal:life.signal});
 const delay=ms=>new Promise(resolve=>{const id=setTimeout(()=>{timers.delete(id);resolve();},ms);timers.add(id);});
 const bind=(selector,event,fn)=>host.querySelectorAll(selector).forEach(el=>listen(el,event,fn));
 const paintLobby=()=>{
  host.innerHTML=`<section class="game-lobby"><div><span class="game-micro">PRACTICE MAKES AN OPERATOR</span><h2>공격자의 시선.<br><em>방어자의 선택.</em></h2><p>가상 봇 NOVA와 겨루세요. 방화벽을 약화시켜 가상 정보 3개를 확보하거나, 몰려오는 바이러스에 맞는 백신으로 내 컴퓨터를 지키세요.</p><div class="game-mode-select" role="group" aria-label="게임 모드"><button data-game-mode="duel" aria-pressed="${mode==='duel'}">공격 + 방어 공방전</button><button data-game-mode="defense" aria-pressed="${mode==='defense'}">백신 방어 미션</button></div><button class="primary-button" id="start-hacking-game">${mode==='duel'?'공방전 시작':'방어 미션 시작'} →</button><small>BEST SCORE / <b>${highScore}</b></small></div><div class="game-lobby-art">${asset('wannacry','랜섬웨어의 3D 상징')}<span>VS</span>${asset('defender','백신 방패의 3D 상징')}<div>VIRUS × ANTIVIRUS</div></div></section>
  <div class="game-howto"><article><span>01 / BREACH</span><h3>방화벽부터 무너뜨리기</h3><p>웜·랜섬웨어 카드로 방어력을 낮추고, 파일 바이러스·트로이목마 카드로 가상 문서를 확보하세요.</p></article><article><span>02 / COUNTER</span><h3>들어온 바이러스 격파</h3><p>화면을 돌아다니는 바이러스를 최대 3개 클릭해 피해를 낮추세요. 알려진 패턴은 ClamAV, 복제·잠금 행위는 Defender 카드로 대응하세요.</p></article><article><span>03 / SURVIVE</span><h3>6라운드 끝까지 생존</h3><p>공방전은 가상 정보 3개 확보 + 생존, 방어 미션은 생존이 목표입니다. 결과 화면에서 다시 도전할 수 있습니다.</p></article></div><div class="mission-scope">백신·악성코드의 상징 에셋을 사용하는 게임입니다. 카드의 효과와 상성은 게임 규칙이며 실제 제품 성능을 비교한 결과가 아닙니다.</div>`;
  bind('[data-game-mode]','click',event=>{mode=event.currentTarget.dataset.gameMode;paintLobby();host.querySelector(`[data-game-mode="${mode}"]`).focus({preventScroll:true});});
  listen(host.querySelector('#start-hacking-game'),'click',()=>{generation++;state=newMatch(mode,Math.floor(Math.random()*4));paint();host.querySelector('.game-status-title').focus({preventScroll:true});});
 };
 const paint=()=>{
  if(disposed||!state)return;
  const phase=state.phase,incoming=state.incoming||incomingKey(state),threat=ATTACKS[incoming],isDefense=phase==='defense',finished=phase==='finished';
  const title=busy?'패킷 전송 중':phase==='attack'?'공격할 바이러스를 선택하세요':isDefense?'상대의 바이러스가 도착했습니다':finished?(state.won?'MISSION COMPLETE':'MISSION FAILED'):'라운드 결과를 확인하세요';
  host.innerHTML=`<section class="game-dashboard"><div><span>ROUND</span><strong>${state.round}<small> / 06</small></strong></div><div><span>MY INTEGRITY</span><strong class="${state.health<35?'game-danger':''}">${state.health}%</strong></div><div><span>INTEL CAPTURED</span><strong>${state.intel.length}<small> / ${state.mode==='duel'?'03':'—'}</small></strong></div><div><span>SCORE / BEST ${highScore}</span><strong>${state.score}</strong></div></section>
  <div class="game-round-heading"><div><span class="game-micro">${state.mode==='duel'?'ATTACK & DEFENSE':'DEFENSE MISSION'} / ${phase.toUpperCase()}</span><h2 class="game-status-title" tabindex="-1">${title}</h2></div><button class="outline-button" id="leave-game">게임 나가기</button></div>
  <section class="game-stage ${isDefense?'under-attack':''}" data-flow="${busy?'transmitting':'idle'}" aria-label="두 가상 컴퓨터의 전장"><div class="game-computer player"><div class="game-computer-top"><span>YOU / HEX-01</span><span>${state.health?'ONLINE':'OFFLINE'}</span></div><div class="game-computer-screen"><span class="computer-glyph">▣</span><h3>내 가상 컴퓨터</h3><div class="game-health-bar" role="progressbar" aria-label="내 컴퓨터 무결성" aria-valuenow="${state.health}" aria-valuemin="0" aria-valuemax="100"><i style="width:${state.health}%"></i></div><p>INTEGRITY ${state.health}%</p>${isDefense?`<div class="game-threat-field" aria-label="격파할 바이러스">${Array.from({length:3},(_,index)=>`<button class="game-threat ${state.tapped.includes(index)?'neutralized':''}" data-hit-threat="${index}" aria-label="${threat.name} 바이러스 ${index+1} 격파" ${state.tapped.includes(index)||busy?'disabled':''} style="--threat-left:${10+index*28}%;--threat-top:${25+index%2*30}%;--bug-x:${index%2?-24:25}px;--bug-y:${index%2?26:-24}px;--bug-delay:-${index*2}s">${asset(incoming)}<span>${state.tapped.includes(index)?'격파 ✓':'HIT'}</span></button>`).join('')}</div>`:''}</div><div class="computer-stand"></div></div><div class="game-network-link"><span>${isDefense?'← INCOMING':'OUTGOING →'}</span><i></i><div class="game-flying-packet">${asset(state.last?.kind==='attack'?state.last.key||'virus':incoming)}</div><small>ISOLATED NETWORK</small></div><div class="game-computer opponent"><div class="game-computer-top"><span>NOVA / BOT</span><span>TRAINING VM</span></div><div class="game-computer-screen"><span class="computer-glyph">▣</span><h3>상대 가상 컴퓨터</h3><div class="game-health-bar" role="progressbar" aria-label="상대 방화벽" aria-valuenow="${state.firewall}" aria-valuemin="0" aria-valuemax="100"><i style="width:${state.firewall}%"></i></div><p>FIREWALL ${state.firewall}%</p><div class="game-intel-files">${['MISSION.PDF','NETWORK.JSON','NOTES.TXT'].map((name,index)=>`<span class="${index<state.intel.length?'captured':''}">${index<state.intel.length?'✓':'▤'} ${name}</span>`).join('')}</div></div><div class="computer-stand"></div></div></section>
  <div class="game-controls" aria-live="polite">${phase==='attack'?`<div class="game-action-heading"><span>CHOOSE YOUR PAYLOAD</span><p>방화벽을 낮추고 파일·트로이 카드로 가상 정보 확보</p></div><div class="game-attack-cards">${Object.entries(ATTACKS).map(([key,attack])=>`<button class="game-action-card" data-launch-attack="${key}" ${busy?'disabled':''}>${asset(key,attack.name+' 상징')}<strong>${attack.name}</strong><span>방화벽 −${attack.breach}</span><small>${attack.stealAt<0?'방어력 약화 전문':`방화벽 ≤${attack.stealAt}이면 가상 정보 +1`}</small></button>`).join('')}</div>`:isDefense?`<div class="game-action-heading"><span>${threat.name.toUpperCase()} / INCOMING THREAT</span><p>관측 특징: <b>${threat.hint}</b> · 격파 ${state.tapped.length}/3</p></div><div class="game-defense-cards">${Object.entries(DEFENDERS).map(([key,defense])=>`<button class="game-action-card" data-defend-wave="${key}" ${busy?'disabled':''}>${asset(key,defense.name+' 방패 상징')}<strong>${defense.name}</strong><span>${defense.label}</span><small>${defense.hint}</small></button>`).join('')}</div><p class="game-tip">바이러스 3개를 먼저 클릭하면 피해가 감소합니다. 이어서 탐지 방식에 맞는 백신 카드를 선택하세요.</p>`:`<div class="game-round-result ${finished?(state.won?'won':'lost'):''}">${asset(state.last?.matched?'defender':incoming)}<div><span>${finished?(state.won?'VICTORY':'TRY AGAIN'):'WAVE RESOLVED'}</span><h3>${finished?state.finishReason:state.last.message}</h3><p>${finished?`총점 ${state.score} · 생존 ${state.health}% · 가상 정보 ${state.intel.length}/3`:state.last.matched?'탐지 방식이 위협에 맞았습니다. 다음 공격을 준비하세요.':'다음 라운드에서는 위협의 관측 특징에 맞춰 선택하세요.'}</p><button class="primary-button" id="game-next">${finished?'다시 도전하기':'다음 라운드 →'}</button>${finished?'<button class="outline-button" id="game-lobby">미션 선택으로</button>':''}</div></div>`}</div>
  <div class="game-lower-grid"><section class="panel"><div class="panel-header"><h2>CAPTURED INTELLIGENCE</h2><span class="panel-code">SYNTHETIC DATA</span></div><div class="game-intelligence">${state.intel.length?state.intel.map((file,index)=>`<article><span>0${index+1} / COPIED TO HEX-01</span><strong>${file}</strong><p>TRAINING_RECORD_${index+1} · 게임용 가상 문서</p></article>`).join(''):'<p>아직 확보한 가상 정보가 없습니다.</p>'}</div></section><section class="panel"><div class="panel-header"><h2>LIVE MISSION LOG</h2></div><pre class="game-log">${state.log.join('\n')}</pre></section></div><div class="mission-scope">내 컴퓨터와 상대 컴퓨터, 확보하는 정보는 모두 게임 안의 가상 데이터입니다.</div>`;
  host.querySelector('.opponent [role="progressbar"]').setAttribute('aria-valuenow',String(state.firewall));
  listen(host.querySelector('#leave-game'),'click',()=>{generation++;state=null;busy=false;paintLobby();host.querySelector('#start-hacking-game').focus({preventScroll:true});});
  bind('[data-launch-attack]','click',async event=>{
   if(busy||state.phase!=='attack')return;const key=event.currentTarget.dataset.launchAttack,original=state,revision=generation;busy=true;state={...state,last:{kind:'attack',key}};paint();
   await delay(matchMedia('(prefers-reduced-motion: reduce)').matches?100:850);if(disposed||revision!==generation||state===null||state.round!==original.round||state.phase!=='attack')return;
   state=launchAttack(original,key);busy=false;paint();host.querySelector('.game-status-title').focus({preventScroll:true});
  });
  bind('[data-hit-threat]','click',event=>{
   if(busy)return;state=tapThreat(state,Number(event.currentTarget.dataset.hitThreat));const button=event.currentTarget;button.classList.add('neutralized');button.disabled=true;button.querySelector('span').textContent='격파 ✓';host.querySelector('.game-action-heading p').textContent=`관측 특징: ${threat.hint} · 격파 ${state.tapped.length}/3`;host.querySelector('.game-dashboard>div:last-child strong').textContent=state.score;
  });
  bind('[data-defend-wave]','click',async event=>{
   if(busy||state.phase!=='defense')return;const defense=event.currentTarget.dataset.defendWave,original=state,revision=generation;busy=true;paint();host.querySelector('.game-status-title').textContent=DEFENDERS[defense].name+' · 검사·격파 중';host.querySelector('.game-stage').classList.add('defense-pulse');
   await delay(matchMedia('(prefers-reduced-motion: reduce)').matches?100:750);if(disposed||revision!==generation||state===null||state.round!==original.round||state.phase!=='defense')return;
   state=defendWave(original,defense);busy=false;if(state.phase==='finished'&&state.score>highScore){highScore=state.score;try{localStorage.setItem('hexlab-game-best',String(highScore));}catch{}}
   paint();host.querySelector('.game-status-title').focus({preventScroll:true});
  });
  if(host.querySelector('#game-next'))listen(host.querySelector('#game-next'),'click',()=>{if(finished)generation++;state=finished?newMatch(state.mode,Math.floor(Math.random()*4)):nextRound(state);paint();host.querySelector('.game-status-title').focus({preventScroll:true});});
  if(host.querySelector('#game-lobby'))listen(host.querySelector('#game-lobby'),'click',()=>{generation++;state=null;paintLobby();});
 };
 paintLobby();
 return()=>{disposed=true;life.abort();timers.forEach(clearTimeout);timers.clear();};
}
